(java/'AlarmStore.java').write_text('package jp.wakeguard.alarm;\n\nimport android.content.Context;\nimport android.content.SharedPreferences;\nimport org.json.JSONArray;\nimport org.json.JSONObject;\nimport java.util.ArrayList;\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Set;\n\n/** Persistent additional alarms. The original MainActivity alarm remains alarm id=1. */\npublic final class AlarmStore {\n    private static final String FILE = "wake_guard_multi_alarms";\n    private static final String KEY_ALARMS = "alarms_json";\n    private static final String KEY_NEXT_ID = "next_id";\n    private static final String KEY_KNOWN_IDS = "known_ids";\n    private AlarmStore() {}\n\n    public static final class Entry {\n        public long id;\n        public int hour;\n        public int minute;\n        public int dayMask;\n        public boolean enabled;\n        public String label;\n        public Entry(long id, int hour, int minute, int dayMask, boolean enabled, String label) {\n            this.id=id; this.hour=hour; this.minute=minute; this.dayMask=dayMask;\n            this.enabled=enabled; this.label=label==null?"":label;\n        }\n        public boolean oneShot() { return dayMask == 0; }\n    }\n\n    private static SharedPreferences p(Context c) {\n        return c.getSharedPreferences(FILE, Context.MODE_PRIVATE);\n    }\n\n    public static synchronized List<Entry> all(Context c) {\n        ArrayList<Entry> out = new ArrayList<>();\n        String raw = p(c).getString(KEY_ALARMS, "[]");\n        try {\n            JSONArray a = new JSONArray(raw == null ? "[]" : raw);\n            for (int i=0;i<a.length();i++) {\n                JSONObject o=a.optJSONObject(i); if(o==null) continue;\n                long id=o.optLong("id", -1); if(id<1000) continue;\n                out.add(new Entry(id,\n                        Math.max(0,Math.min(23,o.optInt("hour",7))),\n                        Math.max(0,Math.min(59,o.optInt("minute",0))),\n                        o.optInt("days",0) & 0x7F,\n                        o.optBoolean("enabled",true),\n                        o.optString("label","")));\n            }\n        } catch (Throwable ignored) {}\n        return out;\n    }\n\n    private static synchronized void save(Context c, List<Entry> entries) {\n        JSONArray a=new JSONArray();\n        Set<String> known = new HashSet<>(p(c).getStringSet(KEY_KNOWN_IDS, new HashSet<>()));\n        for(Entry e: entries) {\n            try {\n                JSONObject o=new JSONObject();\n                o.put("id",e.id); o.put("hour",e.hour); o.put("minute",e.minute);\n                o.put("days",e.dayMask & 0x7F); o.put("enabled",e.enabled);\n                o.put("label",e.label==null?"":e.label); a.put(o);\n                known.add(String.valueOf(e.id));\n            } catch(Throwable ignored) {}\n        }\n        p(c).edit().putString(KEY_ALARMS,a.toString()).putStringSet(KEY_KNOWN_IDS,known).commit();\n    }\n\n    public static synchronized Entry add(Context c, int hour, int minute, int dayMask, String label) {\n        SharedPreferences sp=p(c);\n        long id=Math.max(1000L, sp.getLong(KEY_NEXT_ID,1000L));\n        sp.edit().putLong(KEY_NEXT_ID,id+1L).commit();\n        List<Entry> list=all(c);\n        Entry e=new Entry(id,hour,minute,dayMask,true,label);\n        list.add(e); save(c,list); return e;\n    }\n\n    public static synchronized void update(Context c, Entry changed) {\n        List<Entry> list=all(c); boolean found=false;\n        for(int i=0;i<list.size();i++) if(list.get(i).id==changed.id){list.set(i,changed);found=true;break;}\n        if(!found) list.add(changed);\n        save(c,list);\n    }\n\n    public static synchronized void setEnabled(Context c, long id, boolean enabled) {\n        List<Entry> list=all(c);\n        for(Entry e:list) if(e.id==id){e.enabled=enabled;break;}\n        save(c,list);\n    }\n\n    public static synchronized void delete(Context c, long id) {\n        List<Entry> list=all(c);\n        list.removeIf(e -> e.id==id);\n        save(c,list);\n    }\n\n    public static synchronized Entry find(Context c, long id) {\n        for(Entry e:all(c)) if(e.id==id) return e;\n        return null;\n    }\n\n    public static synchronized void markFiredIfOneShot(Context c, long id) {\n        if(id<1000) return;\n        Entry e=find(c,id);\n        if(e!=null && e.enabled && e.oneShot()) {\n            e.enabled=false;\n            update(c,e);\n        }\n    }\n\n    public static synchronized long[] knownIds(Context c) {\n        Set<String> s=p(c).getStringSet(KEY_KNOWN_IDS,new HashSet<>());\n        long[] out=new long[s.size()]; int n=0;\n        for(String x:s) { try{out[n++]=Long.parseLong(x);}catch(Throwable ignored){} }\n        if(n==out.length) return out;\n        long[] trimmed=new long[n]; System.arraycopy(out,0,trimmed,0,n); return trimmed;\n    }\n}\n', encoding="utf-8")
(java/'MultiAlarmActivity.java').write_text('package jp.wakeguard.alarm;\n\nimport android.app.*;\nimport android.graphics.Color;\nimport android.graphics.Typeface;\nimport android.os.Bundle;\nimport android.view.*;\nimport android.widget.*;\nimport java.util.List;\n\n/** Unlimited additional WakeGuard alarms. Sound, vibration and step mission settings are shared. */\npublic class MultiAlarmActivity extends Activity {\n    private LinearLayout list;\n    private static final String[] DAY_NAMES={"月","火","水","木","金","土","日"};\n\n    @Override protected void onCreate(Bundle b){\n        super.onCreate(b);\n        build();\n    }\n    @Override protected void onResume(){ super.onResume(); render(); AlarmScheduler.reschedule(this); }\n\n    private Button button(String s){ Button b=new Button(this); b.setText(s); b.setAllCaps(false); return b; }\n    private TextView text(String s,float sp,int color){ TextView v=new TextView(this); v.setText(s);v.setTextSize(sp);v.setTextColor(color);return v; }\n\n    private void build(){\n        LinearLayout outer=new LinearLayout(this); outer.setOrientation(LinearLayout.VERTICAL); outer.setPadding(24,20,24,24);\n        LinearLayout top=new LinearLayout(this); top.setGravity(Gravity.CENTER_VERTICAL);\n        Button back=button("← 戻る"); back.setOnClickListener(v->finish()); top.addView(back);\n        TextView title=text("アラーム",26,Color.BLACK); title.setTypeface(null,Typeface.BOLD); title.setGravity(Gravity.END);\n        top.addView(title,new LinearLayout.LayoutParams(0,-2,1)); outer.addView(top);\n\n        TextView note=text("＋で好きなだけ追加できます。各アラームは時刻・繰り返し・ON/OFF・名前を個別保存。解除歩数・音量・音源・振動は起床ガードの共通設定を使います。曜日を1つも選ばない場合は1回だけ鳴ります。",14,0xFF555555);\n        note.setPadding(0,12,0,10); outer.addView(note);\n        Button add=button("＋ アラームを追加"); add.setOnClickListener(v->editDialog(null)); outer.addView(add);\n\n        ScrollView sv=new ScrollView(this); list=new LinearLayout(this); list.setOrientation(LinearLayout.VERTICAL); list.setPadding(0,8,0,80); sv.addView(list);\n        outer.addView(sv,new LinearLayout.LayoutParams(-1,0,1)); setContentView(outer);\n    }\n\n    private void render(){\n        if(list==null)return; list.removeAllViews();\n        List<AlarmStore.Entry> alarms=AlarmStore.all(this);\n        if(alarms.isEmpty()){\n            TextView empty=text("追加アラームはまだありません。\\n上の「＋ アラームを追加」から作成できます。",17,0xFF666666);\n            empty.setGravity(Gravity.CENTER); empty.setPadding(0,60,0,0); list.addView(empty); return;\n        }\n        for(AlarmStore.Entry e:alarms) addCard(e);\n    }\n\n    private String daysText(AlarmStore.Entry e){\n        if(e.dayMask==0)return "1回のみ";\n        if((e.dayMask&0x7F)==0x7F)return "毎日";\n        StringBuilder b=new StringBuilder();\n        for(int i=0;i<7;i++) if((e.dayMask&(1<<i))!=0){ if(b.length()>0)b.append(\' \'); b.append(DAY_NAMES[i]); }\n        return b.toString();\n    }\n\n    private void addCard(AlarmStore.Entry e){\n        LinearLayout card=new LinearLayout(this); card.setOrientation(LinearLayout.VERTICAL); card.setPadding(20,16,20,16); card.setBackgroundColor(0xFFF3F4F6);\n        LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,10,0,0);\n        LinearLayout row=new LinearLayout(this); row.setGravity(Gravity.CENTER_VERTICAL);\n        TextView time=text(String.format("%02d:%02d",e.hour,e.minute),34,Color.BLACK); time.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);\n        row.addView(time,new LinearLayout.LayoutParams(0,-2,1));\n        Switch sw=new Switch(this); sw.setChecked(e.enabled); row.addView(sw); card.addView(row);\n        String label=e.label==null||e.label.trim().isEmpty()?"アラーム":e.label.trim();\n        TextView detail=text(label+"  •  "+daysText(e),15,0xFF555555); detail.setPadding(0,2,0,10); card.addView(detail);\n        LinearLayout actions=new LinearLayout(this);\n        Button edit=button("編集"); Button del=button("削除");\n        actions.addView(edit,new LinearLayout.LayoutParams(0,-2,1)); actions.addView(del,new LinearLayout.LayoutParams(0,-2,1)); card.addView(actions);\n        sw.setOnCheckedChangeListener((v,on)->{ AlarmStore.setEnabled(this,e.id,on); if(!on)AlarmScheduler.cancelExtraAlarm(this,e.id); AlarmScheduler.reschedule(this); });\n        edit.setOnClickListener(v->editDialog(e));\n        del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("アラームを削除").setMessage(String.format("%02d:%02d を削除しますか？",e.hour,e.minute)).setNegativeButton("キャンセル",null).setPositiveButton("削除",(d,w)->{AlarmScheduler.cancelExtraAlarm(this,e.id);AlarmStore.delete(this,e.id);AlarmScheduler.reschedule(this);render();}).show());\n        list.addView(card,cp);\n    }\n\n    private void editDialog(AlarmStore.Entry existing){\n        LinearLayout box=new LinearLayout(this); box.setOrientation(LinearLayout.VERTICAL); int pad=24; box.setPadding(pad,8,pad,0);\n        TimePicker tp=new TimePicker(this); tp.setIs24HourView(true); tp.setHour(existing==null?7:existing.hour); tp.setMinute(existing==null?0:existing.minute); box.addView(tp);\n        EditText label=new EditText(this); label.setHint("名前（例：学校・休日）"); label.setText(existing==null?"":existing.label); box.addView(label);\n        TextView rep=text("繰り返し（未選択＝1回のみ）",15,0xFF555555); rep.setPadding(0,10,0,4); box.addView(rep);\n        LinearLayout drow=new LinearLayout(this); drow.setOrientation(LinearLayout.HORIZONTAL);\n        CheckBox[] checks=new CheckBox[7]; int mask=existing==null?0:existing.dayMask;\n        for(int i=0;i<7;i++){ checks[i]=new CheckBox(this); checks[i].setText(DAY_NAMES[i]); checks[i].setChecked((mask&(1<<i))!=0); drow.addView(checks[i],new LinearLayout.LayoutParams(0,-2,1)); }\n        HorizontalScrollView hsv=new HorizontalScrollView(this); hsv.addView(drow); box.addView(hsv);\n        new AlertDialog.Builder(this).setTitle(existing==null?"アラームを追加":"アラームを編集").setView(box).setNegativeButton("キャンセル",null).setPositiveButton("保存",(d,w)->{\n            int m=0; for(int i=0;i<7;i++)if(checks[i].isChecked())m|=1<<i;\n            if(existing==null) AlarmStore.add(this,tp.getHour(),tp.getMinute(),m,label.getText().toString().trim());\n            else { existing.hour=tp.getHour();existing.minute=tp.getMinute();existing.dayMask=m;existing.label=label.getText().toString().trim();AlarmStore.update(this,existing); }\n            AlarmScheduler.reschedule(this); render();\n        }).show();\n    }\n}\n', encoding="utf-8")
(java/'AlarmScheduler.java').write_text('package jp.wakeguard.alarm;\n\nimport android.app.AlarmManager;\nimport android.app.ActivityOptions;\nimport android.app.PendingIntent;\nimport android.content.Context;\nimport android.content.Intent;\nimport android.net.Uri;\nimport android.os.Build;\nimport java.time.*;\nimport java.util.*;\n\npublic final class AlarmScheduler {\n    private AlarmScheduler() {}\n    private static final int RECOVERY_REQUEST = 299999;\n    public static final long PRIMARY_ALARM_ID = 1L;\n\n    private static int code(long alarmId, LocalDate d, int kind) {\n        long x = alarmId * 1103515245L + d.toEpochDay() * 2654435761L + kind * 1000003L;\n        return (int)(Math.abs(x) % 2000000000L);\n    }\n\n    private static Uri data(long alarmId, LocalDate d, String kind) {\n        return Uri.parse("wakeguard://alarm/" + alarmId + "/" + d.toEpochDay() + "/" + kind);\n    }\n\n    private static PendingIntent activityPi(Context c, int requestCode, Intent i, int flags) {\n        int f = flags | PendingIntent.FLAG_IMMUTABLE;\n        if (Build.VERSION.SDK_INT >= 34) {\n            ActivityOptions ao = ActivityOptions.makeBasic();\n            ao.setPendingIntentCreatorBackgroundActivityStartMode(ActivityOptions.MODE_BACKGROUND_ACTIVITY_START_ALLOWED);\n            return PendingIntent.getActivity(c, requestCode, i, f, ao.toBundle());\n        }\n        return PendingIntent.getActivity(c, requestCode, i, f);\n    }\n\n    private static PendingIntent scheduledActivityPi(Context c, long alarmId, LocalDate date, int flags) {\n        Intent i = new Intent(c, AlarmActivity.class)\n                .setAction(AlarmActivity.ACTION_SCHEDULED_FIRE)\n                .setData(data(alarmId,date,"fire"))\n                .putExtra(AlarmService.EXTRA_EPOCH_DAY, date.toEpochDay())\n                .putExtra(AlarmActivity.EXTRA_ALARM_ID, alarmId)\n                .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_SINGLE_TOP | Intent.FLAG_ACTIVITY_CLEAR_TOP);\n        return activityPi(c, code(alarmId,date,1), i, flags);\n    }\n\n    private static PendingIntent showAlarmUiPi(Context c, long alarmId, LocalDate date, int flags) {\n        Intent i = new Intent(c, AlarmActivity.class)\n                .setAction("jp.wakeguard.alarm.SHOW_RUNNING_ALARM")\n                .setData(data(alarmId,date,"show"))\n                .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_SINGLE_TOP | Intent.FLAG_ACTIVITY_CLEAR_TOP | Intent.FLAG_ACTIVITY_NO_USER_ACTION);\n        return activityPi(c, code(alarmId,date,2), i, flags);\n    }\n\n    private static PendingIntent backupFirePi(Context c, long alarmId, LocalDate date, int flags) {\n        Intent i = new Intent(c, AlarmReceiver.class)\n                .setAction(AlarmReceiver.ACTION_BACKUP_FIRE)\n                .setData(data(alarmId,date,"backup"))\n                .putExtra("epochDay", date.toEpochDay())\n                .putExtra("alarmId", alarmId);\n        return PendingIntent.getBroadcast(c, code(alarmId,date,3), i, flags | PendingIntent.FLAG_IMMUTABLE);\n    }\n\n    private static boolean selected(LocalDate date, int mask) {\n        int idx=date.getDayOfWeek().getValue()-1;\n        return (mask & (1<<idx))!=0;\n    }\n\n    public static boolean canScheduleExact(Context c) {\n        AlarmManager am=c.getSystemService(AlarmManager.class);\n        return am!=null && (Build.VERSION.SDK_INT<31 || am.canScheduleExactAlarms());\n    }\n\n    private static void cancelPair(Context c, AlarmManager am, long id, LocalDate d) {\n        PendingIntent fire=scheduledActivityPi(c,id,d,PendingIntent.FLAG_NO_CREATE); if(fire!=null)am.cancel(fire);\n        PendingIntent show=showAlarmUiPi(c,id,d,PendingIntent.FLAG_NO_CREATE); if(show!=null)am.cancel(show);\n        PendingIntent backup=backupFirePi(c,id,d,PendingIntent.FLAG_NO_CREATE); if(backup!=null)am.cancel(backup);\n    }\n\n    /** Cancel the v0.6/v0.7 primary PendingIntents that did not carry alarm ids. */\n    private static void cancelLegacyPrimary(Context c, AlarmManager am, LocalDate today) {\n        for(int i=-2;i<=120;i++) {\n            LocalDate d=today.plusDays(i);\n            int old=300000+(int)(d.toEpochDay()%100000);\n            Intent fireI=new Intent(c,AlarmActivity.class).setAction(AlarmActivity.ACTION_SCHEDULED_FIRE)\n                    .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);\n            PendingIntent fire=activityPi(c,old,fireI,PendingIntent.FLAG_NO_CREATE); if(fire!=null)am.cancel(fire);\n            Intent showI=new Intent(c,AlarmActivity.class).setAction("jp.wakeguard.alarm.SHOW_RUNNING_ALARM")\n                    .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_NO_USER_ACTION);\n            PendingIntent show=activityPi(c,old+400000,showI,PendingIntent.FLAG_NO_CREATE); if(show!=null)am.cancel(show);\n            Intent backupI=new Intent(c,AlarmReceiver.class).setAction(AlarmReceiver.ACTION_BACKUP_FIRE);\n            PendingIntent backup=PendingIntent.getBroadcast(c,old+200000,backupI,PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE); if(backup!=null)am.cancel(backup);\n        }\n    }\n\n    public static void cancelExtraAlarm(Context c,long alarmId) {\n        try {\n            AlarmManager am=c.getSystemService(AlarmManager.class); if(am==null)return;\n            ZoneId zone=ZoneId.systemDefault(); LocalDate today=LocalDate.now(zone);\n            for(int i=-2;i<=120;i++) cancelPair(c,am,alarmId,today.plusDays(i));\n        } catch(Throwable ignored) {}\n    }\n\n    private static int scheduleSpec(Context c, AlarmManager am, long id, int hour, int minute, int mask, boolean enabled, boolean primary, ZoneId zone, LocalDate today, Instant now) {\n        if(!enabled)return 0;\n        int count=0;\n        for(int i=0;i<=120 && count<14;i++) {\n            LocalDate d=today.plusDays(i);\n            if(mask!=0 && !selected(d,mask))continue;\n            ZonedDateTime when=d.atTime(hour,minute).atZone(zone);\n            if(!when.toInstant().isAfter(now.plusSeconds(2)))continue;\n\n            PendingIntent fire=scheduledActivityPi(c,id,d,PendingIntent.FLAG_UPDATE_CURRENT);\n            Intent open=new Intent(c, primary?MainActivity.class:MultiAlarmActivity.class);\n            open.setData(data(id,d,"open"));\n            PendingIntent showPi=activityPi(c,code(id,d,4),open,PendingIntent.FLAG_UPDATE_CURRENT);\n            AlarmManager.AlarmClockInfo info=new AlarmManager.AlarmClockInfo(when.toInstant().toEpochMilli(),showPi);\n            am.setAlarmClock(info,fire);\n\n            PendingIntent show=showAlarmUiPi(c,id,d,PendingIntent.FLAG_UPDATE_CURRENT);\n            long showAt=when.toInstant().toEpochMilli()+900L;\n            if(Build.VERSION.SDK_INT>=23)am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,showAt,show); else am.setExact(AlarmManager.RTC_WAKEUP,showAt,show);\n\n            PendingIntent backup=backupFirePi(c,id,d,PendingIntent.FLAG_UPDATE_CURRENT);\n            long backupAt=when.toInstant().toEpochMilli()+1500L;\n            if(Build.VERSION.SDK_INT>=23)am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,backupAt,backup); else am.setExact(AlarmManager.RTC_WAKEUP,backupAt,backup);\n            count++;\n            if(mask==0)break; // additional alarm with no selected weekday = one-shot\n        }\n        return count;\n    }\n\n    public static void reschedule(Context c) {\n        try {\n            AlarmManager am=c.getSystemService(AlarmManager.class); if(am==null||!canScheduleExact(c))return;\n            ZoneId zone=ZoneId.systemDefault(); LocalDate today=LocalDate.now(zone); Instant now=Instant.now();\n            cancelLegacyPrimary(c,am,today);\n            // New identities can be cancelled deterministically. This also clears old times after editing.\n            for(int i=-2;i<=120;i++) cancelPair(c,am,PRIMARY_ALARM_ID,today.plusDays(i));\n            for(long id:AlarmStore.knownIds(c)) for(int i=-2;i<=120;i++) cancelPair(c,am,id,today.plusDays(i));\n\n            scheduleSpec(c,am,PRIMARY_ALARM_ID,Prefs.hour(c),Prefs.minute(c),Prefs.dayMask(c),Prefs.enabled(c),true,zone,today,now);\n            for(AlarmStore.Entry e:AlarmStore.all(c))\n                scheduleSpec(c,am,e.id,e.hour,e.minute,e.dayMask,e.enabled,false,zone,today,now);\n        } catch(Throwable t) {\n            try{Prefs.lastAlarmError(c,"AlarmScheduler: "+t.getClass().getSimpleName()+(t.getMessage()==null?"":": "+t.getMessage()));}catch(Throwable ignored){}\n        }\n    }\n\n    public static void scheduleRecoveryIfActive(Context c) {\n        try {\n            if(!Prefs.active(c)||!canScheduleExact(c))return;\n            AlarmManager am=c.getSystemService(AlarmManager.class); if(am==null)return;\n            Intent i=new Intent(c,AlarmReceiver.class).setAction(AlarmReceiver.ACTION_RECOVER);\n            PendingIntent pi=PendingIntent.getBroadcast(c,RECOVERY_REQUEST,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);\n            long at=System.currentTimeMillis()+3000L;\n            Intent show=new Intent(c,MainActivity.class);\n            PendingIntent showPi=activityPi(c,RECOVERY_REQUEST+1,show,PendingIntent.FLAG_UPDATE_CURRENT);\n            am.setAlarmClock(new AlarmManager.AlarmClockInfo(at,showPi),pi);\n        } catch(Throwable t) { try{Prefs.lastAlarmError(c,"RecoveryAlarm: "+t.getClass().getSimpleName());}catch(Throwable ignored){} }\n    }\n\n    private static long nextFor(int h,int m,int mask,boolean enabled,ZoneId zone,LocalDate today,Instant now) {\n        if(!enabled)return -1L;\n        for(int i=0;i<=120;i++) {\n            LocalDate d=today.plusDays(i); if(mask!=0&&!selected(d,mask))continue;\n            Instant x=d.atTime(h,m).atZone(zone).toInstant(); if(x.isAfter(now))return x.toEpochMilli();\n            if(mask==0 && i>0)break;\n        }\n        return -1L;\n    }\n\n    public static long nextTriggerMillis(Context c) {\n        ZoneId zone=ZoneId.systemDefault(); LocalDate today=LocalDate.now(zone); Instant now=Instant.now(); long best=-1;\n        long p=nextFor(Prefs.hour(c),Prefs.minute(c),Prefs.dayMask(c),Prefs.enabled(c),zone,today,now); if(p>0)best=p;\n        for(AlarmStore.Entry e:AlarmStore.all(c)) {\n            long x=nextFor(e.hour,e.minute,e.dayMask,e.enabled,zone,today,now); if(x>0&&(best<0||x<best))best=x;\n        }\n        return best;\n    }\n}\n', encoding="utf-8")

